# app/main.py  (minutes 15-25: scaffold)
from fastapi import FastAPI
from pydantic import BaseModel, Field

app = FastAPI(title="Ticket triage")

class TicketIn(BaseModel):
    text: str = Field(min_length=1, max_length=5000)

class TicketOut(BaseModel):
    category: str
    confidence: float

@app.get("/health")
def health():
    return {"status": "ok"}

@app.post("/triage", response_model=TicketOut)
def triage(t: TicketIn) -> TicketOut:
    # core path first: a simple rule, swap in an LLM later
    if "refund" in t.text.lower():
        return TicketOut(category="billing", confidence=0.9)
    return TicketOut(category="general", confidence=0.5)

# tests/test_main.py  (minutes 55-70)
from fastapi.testclient import TestClient
from app.main import app
client = TestClient(app)

def test_refund_is_billing():
    r = client.post("/triage", json={"text": "I want a refund"})
    assert r.status_code == 200 and r.json()["category"] == "billing"

def test_empty_text_rejected():
    assert client.post("/triage", json={"text": ""}).status_code == 422
